import time, json, requests
from threading import Lock, Timer

BATCH = []
BATCH_LOCK = Lock()

def send_batch():
    global BATCH
    with BATCH_LOCK:
        batch = BATCH
        BATCH = []
    if not batch:
        return
    payload = {
        'inputs': [r['input'] for r in batch],
        'metadata': {'trace': 'lab-demo'}
    }
    resp = requests.post('http://localhost:12345/generate', json=payload, timeout=5)
    for i, r in enumerate(batch):
        r['future'].set_result(resp.json()['outputs'][i])

