# simple LRU prefetch example (concept):
class SimpleLRU:
    def __init__(self, capacity):
        self.store = {}
        self.order = []
        self.cap = capacity
    def get(self, key):
        if key in self.store:
            self.order.remove(key); self.order.append(key); return self.store[key]
        return None
    def put(self, key, value):
        if key in self.store: self.order.remove(key)
        self.store[key]=value; self.order.append(key)
        if len(self.order)>self.cap: oldest=self.order.pop(0); del self.store[oldest]

