// simplified: pump collects up to maxBatch items or until maxDelay
func pump(ch chan Request, maxBatch int, maxDelay time.Duration) {
    var buf []Request
    timer := time.NewTimer(maxDelay)
    for {
        select {
        case r := <-ch:
            buf = append(buf, r)
            if len(buf) >= maxBatch { flush(buf); buf = nil; timer.Reset(maxDelay) }
        case <-timer.C:
            if len(buf)>0 { flush(buf); buf = nil }
            timer.Reset(maxDelay)
        }
    }
}
